using System;using System.IO;using System.IO.Compression;using System.Linq;using System.Threading;using System.Threading.Tasks;using UnityEngine;using UnityEditor;using RailDrivingSimulator;
public static class IOSLogicTests {
 static void Assert(bool b,string m){if(!b)throw new Exception(m);}
 public static void Run(){string dir="/Volumes/RailRestoreWork/LogicTests";Directory.CreateDirectory(dir);MobileInput.Clear();MobileInput.Press("惰行");Assert(MobileInput.Down("惰行")&&!MobileInput.Down("惰行"),"edge input");MobileInput.Hold("防失能",1,true);MobileInput.Hold("防失能",2,true);MobileInput.Hold("防失能",1,false);Assert(MobileInput.Held("防失能"),"multi touch");MobileInput.Clear();Assert(!MobileInput.Held("防失能"),"focus clear");
 string source="/Volumes/RailRestoreWork/MapMetadata";var manifest=JsonUtility.FromJson<MapManifest>(File.ReadAllText(source+"/manifest.json"));foreach(var entry in manifest.routes){var r=JsonUtility.FromJson<RouteData>(File.ReadAllText(source+"/"+entry.file));r.Validate();RunPlan cp;var compiled=JourneyPlanner.Compile(r,new RunPlan{routeId=r.id,start=0,end=0,selected=Enumerable.Repeat(true,r.stations.Length).ToArray(),difficulty=Difficulty.Hard},out cp);var sim=new Simulation(compiled,cp);sim.ChangeNotch(2);for(int i=0;i<150;i++)sim.Tick(.02,true);Assert(sim.state.v>0,"power");sim.Tick(.02,false);Assert(sim.state.emergency,"vigilance release");for(int i=0;i<4000;i++)sim.Tick(.02,true);sim.Neutral();Assert(sim.state.v==0&&sim.state.a==0&&sim.ResetEmergency(),"EB reset");sim.state.v=0;while(!sim.state.finished){sim.state.s=sim.Next.Target(cp.train.length);Assert(sim.OpenDoor(),"open");for(int i=0;i<10;i++)sim.Tick(.02,true);sim.CloseDoor();for(int i=0;i<12;i++)sim.Tick(.02,true);}Assert(sim.state.served.Count==30,"full loop stops");}
 Debug.Log("IOS_BASELINE_ROUTE_PASS directions=2 served_per_direction=30 EB_reset=true");
 string input=dir+"/Fixture";Directory.CreateDirectory(input);File.WriteAllBytes(input+"/shared.bundle",new byte[32768]);File.WriteAllBytes(input+"/chunk.bundle",new byte[32768]);File.WriteAllText(input+"/route.json",File.ReadAllText(source+"/route.json"));var m=new MapManifest{platform=MapCatalog.Platform,id="IOS_FIXTURE",name="fixture",routeSha256=Storage.SHA(input+"/route.json"),shared="shared.bundle",sharedSha256=Storage.SHA(input+"/shared.bundle"),chunks=new[]{new ChunkRecord{file="chunk.bundle",sha256=Storage.SHA(input+"/chunk.bundle")}}};File.WriteAllText(input+"/manifest.json",JsonUtility.ToJson(m));string zip=dir+"/fixture.railmap";if(File.Exists(zip))File.Delete(zip);ZipFile.CreateFromDirectory(input,zip);var job=new MapImportJob(zip,dir+"/Installed");Task.Run(()=>job.Extract(CancellationToken.None)).GetAwaiter().GetResult();var imported=job.Commit();Assert(imported.manifest.platform==MapCatalog.Platform,"platform");Directory.Delete(imported.folder,true);m.platform=MapCatalog.Platform=="iOS"?"StandaloneOSX":"iOS";File.WriteAllText(input+"/manifest.json",JsonUtility.ToJson(m));File.Delete(zip);ZipFile.CreateFromDirectory(input,zip);bool rejected=false;try{new MapImportJob(zip,dir+"/Installed");}catch(InvalidDataException){rejected=true;}Assert(rejected,"wrong platform accepted");
 string result="IOS_LOGIC_PASS multitouch=true edge_input=true background_clear=true vigilance_EB=true EB_reset=true both_routes_30_stops=true streaming_import=true wrong_platform_rejected=true";File.WriteAllText(dir+"/result.txt",result);Debug.Log(result);}
 public static void Preflight(){try{Run();EditorApplication.Exit(0);}catch(Exception e){Debug.LogException(e);EditorApplication.Exit(1);}}
}
